WITH "__os_timechart_source" AS (SELECT "_time" AS "__os_tc_event_time", "host" AS "__os_tc_value", toUInt8(1) AS "__os_tc_present", if(isNull("host"), 'None', 'String') AS "__os_tc_value_type" FROM (SELECT * FROM (SELECT "event_id" AS "event_id", "index_name" AS "index", "event_time" AS "_time", "index_time" AS "_indextime", "host" AS "host", "source" AS "source", "sourcetype" AS "sourcetype", "service" AS "service", "severity" AS "severity", "level" AS "level", "body" AS "message", "raw" AS "_raw", "raw_encoding" AS "__os_raw_encoding", "trace_id" AS "trace_id", "span_id" AS "span_id", "collector_id" AS "collector_id", "batch_id" AS "batch_id", "fields" AS "__os_fields", "field_names" AS "__os_field_names", "field_types" AS "__os_field_types", "field_metadata_version" AS "__os_field_metadata_version", "event_time" AS "__os_sort_time", "event_id" AS "__os_sort_event_id", "visibility_seq" AS "__os_sort_visibility_seq", tuple("index_name", "collector_id", "batch_sequence", "batch_id") AS "__os_sort_source_identity" FROM "open_splunk"."events" WHERE "tenant_id" = ? AND "index_name" IN (?) AND "event_time" >= parseDateTime64BestEffort(?, 9, 'UTC') AND "event_time" < parseDateTime64BestEffort(?, 9, 'UTC') AND "index_time" <= parseDateTime64BestEffort(?, 3, 'UTC') AND "expires_at" > parseDateTime64BestEffort(?, 3, 'UTC') AND "visibility_seq" <= ?) AS "_stage_1" WHERE (1 AND ifNull("index" = ?, 0))) AS "_stage_2"), "__os_timechart_prepared" AS (SELECT *, toUInt8(0) AS "__os_tc_descendant", reinterpretAsInt64("__os_tc_event_time") AS "__os_tc_ticks", if("__os_tc_present" != 0 AND isNotNull("__os_tc_value") AND "__os_tc_value_type" = 'String', assumeNotNull(toString("__os_tc_value")), CAST('' AS String)) AS "__os_tc_label" FROM "__os_timechart_source"), "__os_timechart_classified" AS (SELECT intDiv("__os_tc_ticks", ?) - if("__os_tc_ticks" < 0 AND "__os_tc_ticks" % ? != 0, 1, 0) AS "__os_tc_bucket_number", multiIf("__os_tc_descendant" != 0, toUInt8(3), "__os_tc_present" = 0 OR isNull("__os_tc_value") OR "__os_tc_value_type" = 'None', toUInt8(1), "__os_tc_value_type" != 'String', toUInt8(3), NOT (isValidUTF8("__os_tc_label") AND length("__os_tc_label") BETWEEN 1 AND 256 AND "__os_tc_label" NOT IN ('NULL', 'OTHER')), toUInt8(3), toUInt8(0)) AS "__os_tc_kind", "__os_tc_label" FROM "__os_timechart_prepared"), "__os_timechart_canonicalized" AS (SELECT "__os_tc_bucket_number", "__os_tc_kind", if("__os_tc_kind" = 0, "__os_tc_label", CAST('' AS String)) AS "__os_tc_label" FROM "__os_timechart_classified"), "__os_timechart_group_counts" AS (SELECT "__os_tc_bucket_number", "__os_tc_kind", "__os_tc_label", count() AS "__os_tc_count" FROM "__os_timechart_canonicalized" GROUP BY "__os_tc_bucket_number", "__os_tc_kind", "__os_tc_label"), "__os_timechart_scored" AS (SELECT *, sum(toUInt128("__os_tc_count")) OVER (PARTITION BY "__os_tc_kind", "__os_tc_label") AS "__os_tc_series_score", uniqExact("__os_tc_label") OVER (PARTITION BY "__os_tc_kind", if(startsWith("__os_tc_label", '_'), concat('VALUE', "__os_tc_label"), "__os_tc_label")) AS "__os_tc_collision_cardinality" FROM "__os_timechart_group_counts"), "__os_timechart_ranked" AS (SELECT *, dense_rank() OVER (PARTITION BY "__os_tc_kind" ORDER BY "__os_tc_series_score" DESC, "__os_tc_label" ASC) AS "__os_tc_series_rank" FROM "__os_timechart_scored"), "__os_timechart_collapsed" AS MATERIALIZED (SELECT "__os_tc_bucket_number", multiIf("__os_tc_kind" = 1, '1:', "__os_tc_kind" = 0 AND "__os_tc_series_rank" <= 5, concat('0:', "__os_tc_label"), CAST('' AS String)) AS "__os_tc_encoded", sum("__os_tc_count") AS "__os_tc_collapsed_count", toUInt8(sumIf("__os_tc_count", "__os_tc_kind" = 3) > 0) AS "__os_tc_invalid", toUInt8(maxIf("__os_tc_collision_cardinality", "__os_tc_kind" = 0) > 1) AS "__os_tc_collision" FROM "__os_timechart_ranked" GROUP BY "__os_tc_bucket_number", "__os_tc_encoded"), "__os_timechart_domain_rows" AS (SELECT multiIf("__os_tc_encoded" = '1:', toUInt8(1), "__os_tc_encoded" = '2:', toUInt8(2), toUInt8(0)) AS sort_kind, if(startsWith("__os_tc_encoded", '0:'), if(startsWith(substring("__os_tc_encoded", 3), '_'), concat('VALUE', substring("__os_tc_encoded", 3)), substring("__os_tc_encoded", 3)), CAST('' AS String)) AS "__os_tc_sort_label", "__os_tc_encoded" FROM "__os_timechart_collapsed" WHERE "__os_tc_encoded" != '' AND "__os_tc_collapsed_count" > 0 GROUP BY "__os_tc_encoded"), "__os_timechart_domain" AS (SELECT arrayMap(item -> item.3, arraySort(item -> (item.1, item.2), groupArray((sort_kind, "__os_tc_sort_label", "__os_tc_encoded")))) AS names FROM "__os_timechart_domain_rows"), "__os_timechart_bucket_maps" AS (SELECT "__os_tc_bucket_number", mapFromArrays(arrayPushBack(groupArrayIf("__os_tc_encoded", "__os_tc_encoded" != ''), CAST('' AS String)), arrayPushBack(groupArrayIf("__os_tc_collapsed_count", "__os_tc_encoded" != ''), toUInt64(max("__os_tc_invalid" != 0 OR "__os_tc_collision" != 0)))) AS "__os_tc_count_map" FROM "__os_timechart_collapsed" GROUP BY "__os_tc_bucket_number"), "__os_timechart_grid" AS (SELECT toUInt64(number) AS "__os_timechart_ordinal", toInt64(?) + toInt64(number) AS "__os_tc_bucket_number" FROM numbers(?)) SELECT "__os_timechart_grid"."__os_timechart_ordinal" AS "__os_timechart_ordinal", if("__os_timechart_grid"."__os_timechart_ordinal" = 0, "__os_timechart_domain".names, CAST([], 'Array(String)')) AS "__os_timechart_names", arrayMap(name -> ifNull("__os_timechart_bucket_maps"."__os_tc_count_map"[name], toUInt64(0)), "__os_timechart_domain".names) AS "__os_timechart_counts", toUInt8(ifNull("__os_timechart_bucket_maps"."__os_tc_count_map"[''], toUInt64(0)) != 0) AS "__os_timechart_invalid" FROM "__os_timechart_grid" CROSS JOIN "__os_timechart_domain" LEFT JOIN "__os_timechart_bucket_maps" ON "__os_timechart_bucket_maps"."__os_tc_bucket_number" = "__os_timechart_grid"."__os_tc_bucket_number" ORDER BY "__os_timechart_grid"."__os_timechart_ordinal" ASC SETTINGS enable_materialized_cte = 1
